 function inspect(t,remove=[]){const cols="ABCDEFGHJ",b={};for(const line of t.split("\n")){const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}for(const p of remove)b[p]=".";const ns=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};const seen=new Set(),groups=[],regions=[];for(const p in b){if(seen.has(p))continue;let q=[p],ps=[],libs=new Set(),boundary=new Set();seen.add(p);while(q.length){const a=q.pop();ps.push(a);for(const n of ns(a)){if(b[n]===b[p]&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!==b[p]){if(b[n]===".")libs.add(n);else boundary.add(b[n]);}}}if(b[p]===".")regions.push({points:ps.sort(),boundary:[...boundary]});else groups.push({color:b[p],stones:ps.sort(),liberties:[...libs].sort()});}const stones={X:0,O:0};for(const v of Object.values(b))if(v!==".")stones[v]++;const area={...stones,neutral:0};for(const r of regions)if(r.boundary.length===1)area[r.boundary[0]]+=r.points.length;else area.neutral+=r.points.length;return {board:b,groups,regions,stones,area};};

